function uploadRaw(file,onprogress){return new Promise((resolve,reject)=>{const x=new XMLHttpRequest();x.open('POST','/api/files/upload');x.setRequestHeader('x-csrf-token',S.csrf);x.setRequestHeader('x-file-name',encodeURIComponent(file.name));x.setRequestHeader('x-file-type',file.type||'application/octet-stream');x.upload.onprogress=e=>{if(e.lengthComputable)onprogress(Math.round(e.loaded/e.total*100))};x.onload=()=>{let j={};try{j=JSON.parse(x.responseText)}catch{}x.status>=200&&x.status<300?resolve(j):reject(Error(j.error?.message||'Upload failed (HTTP '+x.status+')'))};x.onerror=()=>reject(Error('Upload failed. Check that Fabric is still running.'));x.send(file)})}
async function upload(e){const list=[...(e?.target?.files||e||[])];if(!list.length)return;for(const f of list){try{S.uploadProgress={name:f.name,percent:0};if(S.page==='Chat')renderChat();else if(S.page==='Files')await files();const x=await uploadRaw(f,p=>{S.uploadProgress={name:f.name,percent:p};const el=$('.upload-inline');if(el){el.lastElementChild.textContent=f.name+' · '+p+'%';el.querySelector('progress').value=p}const panel=$('.upload-panel');if(panel){panel.querySelector('progress').value=p;panel.lastElementChild.textContent=p+'%'}});if(S.page==='Chat')S.attached=[...S.attached.filter(y=>y.id!==x.id),{id:x.id,name:x.name,kind:x.kind,status:x.status}].slice(-10);toast(f.name+' uploaded and queued for analysis')}catch(err){toast(err.message,true)}}S.uploadProgress=null;if(S.page==='Files')await files();else if(S.page==='Chat')renderChat()}function chatPluginPicker(){const rows=S.pluginConnections.length?S.pluginConnections.map(x=>'<label class="chat-plugin-option"><input type="checkbox" data-chat-plugin="'+x.id+'" '+(S.chatPlugins.includes(x.id)?'checked':'')+'><span class="plugin-logo">'+esc((S.plugins.find(p=>p.id===x.pluginId)||{}).icon||'⌘')+'</span><span><b>'+esc(x.name)+'</b><small>Allow this conversation to read from the connected app</small></span></label>').join(''):'<div class="mini-empty">No plugins connected. Open Plugins to authorize an app.</div>';modal('Use plugins in chat','<div class="chat-plugin-picker">'+rows+'</div><p class="form-hint">Fabric reads only the selected app context for your next messages. External actions require explicit approval in the connected service.</p>',async()=>{S.chatPlugins=$$('[data-chat-plugin]').filter(x=>x.checked).map(x=>x.dataset.chatPlugin);renderChat()})}
async function send(regenerate=false){if(typeof regenerate!=='boolean')regenerate=false;if(S.abort){S.abort.abort();return}const el=$('.prompt'),text=el.value.trim();if(!text)return;if(S.listening)try{S.recognition?.stop()}catch{}S.listening=false;const pid=S.chatProviderId,model=S.chatModelId,temp=S.temperature,maxTokens=S.maxTokens,share=S.attached.length>0,pr=activeProvider(),mode=S.chatMode,researchUrls=[...S.researchUrls],performance=S.performance;if(!pid)return toast('Select a model first',true);if(!model)return toast('Open model settings and load a model before chatting',true);S.convo.messages=[...(S.convo.messages||[]),...(regenerate?[]:[{role:'user',content:text,mode}]),{role:'assistant',content:'',providerId:pid,providerName:pr.name,model,mode,performance,sources:[],statusText:'Preparing context…'}];renderChat();const out=S.convo.messages.at(-1);S.abort=new AbortController();$('.send').textContent='Stop';let paintQueued=false,paint=()=>{paintQueued=false;const body=$$('.mbody').at(-1);if(body)body.innerHTML=out.content?md(out.content):'<div class="generation-state"><span class="pulse-core"></span><span>'+esc(out.statusText||'Generating…')+'</span></div>';const box=$('.messages');if(box)box.scrollTop=box.scrollHeight},schedule=()=>{if(!paintQueued){paintQueued=true;requestAnimationFrame(paint)}};try{const r=await fetch('/api/chat/stream',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json','x-csrf-token':S.csrf},body:JSON.stringify({conversationId:S.convo.id,regenerate,providerId:pid,model,temperature:temp,maxTokens,mode,performance,researchUrls,content:text,fileIds:S.attached.map(x=>x.id),includeFileContext:share,pluginConnectionIds:S.chatPlugins}),signal:S.abort.signal});if(!r.ok)throw Error((await r.json()).error.message);const rd=r.body.getReader(),dc=new TextDecoder();let b='';for(;;){const q=await rd.read();if(q.done)break;b+=dc.decode(q.value,{stream:true});const blocks=b.split('\n\n');b=blocks.pop();for(const z of blocks){const ev=z.match(/event: (.+)/)?.[1],d=z.match(/data: (.+)/)?.[1];if(!d)continue;const j=JSON.parse(d);if(ev==='status'){out.statusText=j.message;schedule()}if(ev==='meta'){out.providerName=j.provider;out.model=j.model;out.mode=j.mode;out.performance=j.performance;out.sources=j.sources||[]}if(ev==='token'){out.content+=j.text;schedule()}if(ev==='done'){out.latencyMs=j.latencyMs;out.ttftMs=j.ttftMs;out.citationValidation=j.citationValidation;paint()}if(ev==='error')throw Error(j.message)}}const spoken=out.content;S.convo=await api('/api/conversations/'+S.convo.id);S.attached=[];S.researchUrls=[];await loadConvos();renderChat();if(S.voiceMode)setTimeout(()=>speakVoice(spoken),80)}catch(e){if(e.name==='AbortError'){out.status='cancelled';out.statusText='Stopped';renderChat()}else{toast(e.message,true);try{await loadProviders();S.chatModelId=null;S.convo=await api('/api/conversations/'+S.convo.id);renderChat()}catch{out.error=e.message;renderChat()}}}finally{S.abort=null;const button=$('.send');if(button)button.textContent='Send'}}
async function compare(){const text=$('.prompt').value.trim();if(!text)return toast('Enter a prompt first',true);modal('Multi-model comparison','<div class="comparison empty">Running enabled models in parallel…</div>');try{const r=await api('/api/chat/compare',{method:'POST',body:JSON.stringify({content:text,providerIds:S.providers.map(x=>x.id).slice(0,4)})});$('.comparison').className='cards comparison';$('.comparison').innerHTML=r.items.map(x=>'<article class="card"><h3>'+esc(x.provider)+'</h3><div class="meta">'+esc(x.model||'')+' · '+x.latencyMs+' ms</div><p>'+(x.error?esc(x.error):md(x.response))+'</p>'+(x.usage?'<div class="meta">Tokens '+esc(JSON.stringify(x.usage))+'</div>':'')+'</article>').join('')}catch(e){toast(e.message,true)}}
function formatDuration(seconds){const n=Math.max(0,Math.round(Number(seconds)||0));if(!n)return'Less than a minute';const h=Math.floor(n/3600),m=Math.floor((n%3600)/60),s=n%60;return(h?h+'h ':'')+(m?m+'m ':'')+(s&&!h?s+'s':'').trim()||'Less than a minute'}function nativeDownloadPanel(n){const active=['starting','installing'].includes(n?.state),failed=!!n?.error;if(!active&&!failed)return'';if(failed)return'<section class="native-download native-download-error" role="alert"><div class="download-head"><b>Fabric1.0 download failed</b></div><p class="provider-error">'+esc(n.error)+'</p><div class="actions"><button class="btn primary native-install" data-component="llm">Retry download</button></div></section>';const done=Number(n?.downloadedBytes||0),total=Number(n?.totalBytes||0),pct=Math.max(0,Math.min(100,Number(n?.percent||0))),filePct=total?Math.max(0,Math.min(100,Math.round(done/total*100))):0;return'<section class="native-download" role="status" aria-live="polite"><div class="download-head"><b>'+(n?.stage||'Preparing Fabric1.0 download')+'</b><strong>'+pct+'%</strong></div><progress max="100" value="'+pct+'"></progress><div class="download-meta"><span>Current file: '+esc(n?.currentFile||'Preparing…')+'</span><span>'+formatBytes(done)+(total?' of '+formatBytes(total)+' · '+filePct+'%':'')+'</span></div><div class="download-meta"><span>'+(n?.bytesPerSecond?formatBytes(n.bytesPerSecond)+'/s':'Calculating speed…')+'</span><span>'+(n?.etaSeconds!=null?'About '+formatDuration(n.etaSeconds)+' remaining':'Calculating time remaining…')+'</span></div></section>'}function pollNativeRuntime(){clearTimeout(S.nativePoll);if(['starting','installing'].includes(S.nativeRuntime?.state))S.nativePoll=setTimeout(async()=>{try{S.nativeRuntime=(await api('/api/runtime')).native;if(S.page==='Studio')studio()}catch(e){toast(e.message,true)}},1000)}function nativeStateCopy(n){if(n?.error)return n.error;if(n?.installed&&n?.voiceInstalled)return n.llmReady||n.voiceReady?'Installed · local services active':'Installed · starts automatically on first use';if(['installing','starting'].includes(n?.state))return n.stage||'Installing';if(n?.installed)return'Fabric1.0 installed · add Fabric Voice when ready';if(n?.voiceInstalled)return'Fabric Voice installed · add Fabric1.0 when ready';return'Not installed'}
async function installNativeComponent(component){try{S.nativeRuntime=await api('/api/native/install',{method:'POST',body:JSON.stringify({component})});toast((component==='voice'?'Fabric Voice':'Fabric1.0')+' download started.');studio()}catch(e){toast(e.message,true)}}
async function startNativeComponent(component){try{S.nativeRuntime=await api('/api/native/start',{method:'POST',body:JSON.stringify({component})});toast((component==='voice'?'Fabric Voice':'Fabric1.0')+' is ready');studio()}catch(e){toast(e.message,true)}}
async function studio(){await loadProviders();const [artifacts,research]=await Promise.all([api('/api/artifacts'),api('/api/research/settings')]);S.artifacts=artifacts.items;S.researchSettings=research;content('<div class="hero native-hero"><div><span class="eyebrow">Built into Fabric</span><h2>Fabric1.0 native intelligence</h2><p>Install the local conversational runtime for real general answers. Task workflows can still run without external API keys.</p></div><button class="btn primary native-chat">Open Chat</button></div><div class="native-runtime-grid"><section class="card native-install-card direct-ready-card"><div class="native-card-head"><span class="native-mark">F</span><div><h3>Fabric1.0</h3><p>Built-in Fabric task profile</p></div><span class="status '+(['starting','installing'].includes(S.nativeRuntime?.state)?'warn':S.nativeRuntime?.installed?'ok':'warn')+'"><i></i>'+(['starting','installing'].includes(S.nativeRuntime?.state)?(S.nativeRuntime.percent||0)+'%':S.nativeRuntime?.installed?'Installed':'Runtime required')+'</span></div><div class="native-component-list"><article><div><span>NATIVE CONVERSATION</span><b>Install the Fabric1.0 runtime for general chat</b><small>Without the runtime, Fabric must not present deterministic task templates as a general language model.</small><div class="actions"><button class="btn primary native-install" data-component="llm">Install Fabric1.0 runtime</button></div></div></article><article><div><span>DIRECT VOICE</span><b>Voice conversation is available in Chat</b><small>Uses your browser speech recognition and speech output. Microphone permission is still required.</small></div></article></div>'+nativeDownloadPanel(S.nativeRuntime)+'<p class="form-hint">Fabric1.0 is a Fabric model profile backed by upstream open-weight assets. It is not newly trained proprietary foundation weights. Install the runtime or configure an external provider for conversational generation.</p></section><section class="card"><h3>Local deep research</h3><p class="muted">Optionally connect your own SearXNG instance. Fabric1.0 can analyze uploaded files without it.</p><div class="field"><label>SearXNG base URL</label><input class="researchurl" value="'+esc(research.url||'')+'" placeholder="http://127.0.0.1:8080"></div><button class="btn saveresearch">Save research URL</button><div class="meta">Environment configured: '+(research.environmentConfigured?'Yes':'No')+'</div></section></div><section class="studio-section"><h3>Task modes</h3><div class="mode-grid">'+Object.entries(taskModes).map(([id,x])=>'<button class="mode-card" data-mode="'+id+'"><b>'+esc(x.name)+'</b><span>'+esc(x.description)+'</span></button>').join('')+'</div></section><section class="studio-section"><div class="section-head"><div><h3>Generated outputs</h3><p class="muted">Save responses from Chat, then download reports or complete projects as ZIP files.</p></div></div>'+rows(S.artifacts,x=>'<div><b>'+esc(x.name)+'</b><div class="meta">'+esc(x.kind)+' · '+x.fileCount+' files · '+x.size+' bytes</div></div><div class="actions"><button class="btn" data-download="'+x.id+'">Download ZIP</button><button class="btn danger" data-artdel="'+x.id+'">Delete</button></div>','No saved outputs yet')+'</section>');$('.native-chat').onclick=()=>go('Chat');$('.saveresearch').onclick=async()=>{S.researchSettings=await api('/api/research/settings',{method:'PATCH',body:JSON.stringify({url:$('.researchurl').value})});toast('Research settings saved')};$$('[data-mode]').forEach(b=>b.onclick=()=>{S.chatMode=b.dataset.mode;go('Chat')});$$('[data-download]').forEach(b=>b.onclick=()=>window.location='/api/artifacts/'+b.dataset.download+'/download');$$('[data-artdel]').forEach(b=>b.onclick=async()=>{if(await deleteStoredItem('artifact',b.dataset.artdel))studio()});$$('.native-install').forEach(b=>b.onclick=()=>installNativeComponent(b.dataset.component));pollNativeRuntime()}

const providerTypeForPreset=value=>value==='ollama'?'ollama':value==='anthropic'?'anthropic':'openai-compatible';
const providerPresets={openai:{label:'OpenAI',baseUrl:'https://api.openai.com/v1'},groq:{label:'Groq',baseUrl:'https://api.groq.com/openai/v1'},mistral:{label:'Mistral',baseUrl:'https://api.mistral.ai/v1'},gemini:{label:'Google Gemini',baseUrl:'https://generativelanguage.googleapis.com/v1beta/openai'},openrouter:{label:'OpenRouter',baseUrl:'https://openrouter.ai/api/v1'},anthropic:{label:'Anthropic',baseUrl:'https://api.anthropic.com/v1'},custom:{label:'Other OpenAI-compatible',baseUrl:''},ollama:{label:'Ollama (local)',baseUrl:'http://127.0.0.1:11434'}};
function providerForm(x={}){const isOllama=x.type==='ollama',base=x.config?.baseUrl||'',model=x.config?.defaultModel||'';return '<div class="field"><label>Provider</label><select class="preset">'+Object.entries(providerPresets).map(([k,v])=>'<option value="'+k+'" '+((isOllama&&k==='ollama')||(!isOllama&&base===v.baseUrl)?'selected':'')+'>'+v.label+'</option>').join('')+'</select></div><div class="field"><label>Name</label><input class="pn" value="'+esc(x.name||'')+'" placeholder="My provider"></div><div class="field"><label>Base URL</label><input class="pu" value="'+esc(base)+'" placeholder="https://api.example.com/v1"></div><div class="field"><label>Default model <span class="meta">(optional)</span></label><input class="pm" value="'+esc(model)+'" placeholder="'+(isOllama?'e.g. llama3.2':'e.g. gpt-4.1-mini')+'"></div><div class="field"><label>API key '+(isOllama?'<span class="meta">(not required for local Ollama)</span>':x.hasCredential?'<span class="meta">(leave blank to keep current key)</span>':'')+'</label><input class="pk" type="password" autocomplete="off" data-lpignore="true" '+(isOllama?'disabled':'')+' placeholder="'+(isOllama?'Not required for local Ollama':'Stored encrypted; never returned')+'"></div>'}
function bindPresetForm(){const preset=$('.preset'),url=$('.pu'),name=$('.pn');if(!preset)return;preset.onchange=()=>{const p=providerPresets[preset.value],ollama=preset.value==='ollama',key=$('.pk'),model=$('.pm');url.value=ollama?(S.ollamaUrl||p.baseUrl):p.baseUrl;if(!name.value.trim()||name.value==='Other OpenAI-compatible')name.value=p.label;if(key){key.value='';key.disabled=ollama;key.placeholder=ollama?'Not required for local Ollama':'Stored encrypted; never returned'}if(model)model.placeholder=ollama?'e.g. llama3.2':'e.g. gpt-4.1-mini'};if(!url.value)preset.onchange()}
async function models(){await loadProviders();const cards=S.providers.map(x=>{if(x.type==='fabric-native')return'<article class="card native-provider-card"><div class="phead"><div class="picon fabric-native-icon">F</div><span class="status ok"><i></i>ready</span></div><h4>Fabric1.0</h4><div class="muted">Built-in Fabric task profile · install the native runtime for general conversation</div><div class="model-pills"><span class="model-pill fabric-model">Fabric1.0</span></div><div class="actions"><button class="btn primary use-native">Use in Chat</button></div></article>';return'<article class="card"><div class="phead"><div class="picon">'+(x.type==='ollama'?'O':x.type==='anthropic'?'A':x.type==='mock'?'M':'AI')+'</div><span class="status '+(x.status==='connected'?'ok':x.status==='error'?'error':'')+'"><i></i>'+esc(x.status)+'</span></div><h4>'+esc(x.name)+'</h4><div class="muted">'+esc(x.type)+' · '+(x.hasCredential?'Credential stored':'No credential')+' · '+(x.models||[]).length+' models</div>'+(x.config?.baseUrl?'<div class="meta endpoint">'+esc(x.config.baseUrl)+'</div>':'')+(x.config?.defaultModel?'<div class="meta">Default: '+esc(x.config.defaultModel)+'</div>':'')+(x.models?.length?'<div class="model-pills">'+x.models.slice(0,10).map(m=>'<span class="model-pill">'+esc(m.name||m.id)+'</span>').join('')+'</div>':'')+(x.lastError?'<div class="provider-error" role="alert">'+esc(x.lastError)+'</div>':'')+'<div class="actions"><button class="btn" data-v="'+x.id+'">Validate</button><button class="btn" data-m="'+x.id+'">Load models</button>'+(x.type==='ollama'?'<button class="btn" data-warm="'+x.id+'">Warm model</button>':'')+(x.type!=='mock'?'<button class="btn" data-c="'+x.id+'">Configure</button>':'')+(!x.isDefault?'<button class="btn" data-d="'+x.id+'">Set default</button>':'')+(x.type!=='mock'?'<button class="btn danger" data-r="'+x.id+'">Remove</button>':'')+'</div></article>'}).join('');content('<div class="hero"><div><span class="eyebrow">Model gateway</span><h2>Models</h2><p>Fabric1.0 is built in. External providers remain optional for users who want additional models.</p></div><button class="btn addp">Add external provider</button></div><div class="cards">'+cards+'</div>');$('.use-native')?.addEventListener('click',()=>go('Chat'));$('.addp').onclick=()=>{modal('Add external provider',providerForm(),async()=>{const preset=$('.preset').value,p=providerPresets[preset],type=providerTypeForPreset(preset);await api('/api/providers',{method:'POST',body:JSON.stringify({type,name:$('.pn').value||p.label,baseUrl:$('.pu').value,defaultModel:$('.pm').value,apiKey:$('.pk').value})});toast('Provider saved. Validate it before use.');openSettings('providers')});bindPresetForm()};$$('[data-c]').forEach(b=>b.onclick=()=>{const x=S.providers.find(p=>p.id===b.dataset.c);modal('Configure '+x.name,providerForm(x),async()=>{await api('/api/providers/'+x.id,{method:'PATCH',body:JSON.stringify({type:providerTypeForPreset($('.preset').value),name:$('.pn').value,baseUrl:$('.pu').value,defaultModel:$('.pm').value,apiKey:$('.pk').disabled?'':$('.pk').value})});toast('Provider configuration updated');openSettings('providers')});bindPresetForm()});$$('[data-v]').forEach(b=>b.onclick=async()=>{try{toast((await api('/api/providers/'+b.dataset.v+'/validate',{method:'POST',body:'{}'})).message);openSettings('providers')}catch(e){toast(e.message,true)}});$$('[data-m]').forEach(b=>b.onclick=async()=>{try{toast((await api('/api/providers/'+b.dataset.m+'/models')).items.length+' models loaded');openSettings('providers')}catch(e){toast(e.message,true)}});$$('[data-warm]').forEach(b=>b.onclick=async()=>{try{toast((await api('/api/providers/'+b.dataset.warm+'/warm',{method:'POST',body:JSON.stringify({model:S.chatModelId||''})})).message)}catch(e){toast(e.message,true)}});$$('[data-d]').forEach(b=>b.onclick=async()=>{await api('/api/providers/'+b.dataset.d+'/default',{method:'POST',body:'{}'});openSettings('providers')});$$('[data-r]').forEach(b=>b.onclick=async()=>{if(confirm('Remove provider and encrypted credential?')){await api('/api/providers/'+b.dataset.r,{method:'DELETE',body:'{}'});openSettings('providers')}})}
async function files(){S.files=(await api('/api/files')).items;content('<div class="hero"><div><span class="eyebrow">Knowledge matrix</span><h2>Universal file intake</h2><p>Stream files directly from your device. Text, Office, PDF, images, audio, video, archives, code, and unknown binary formats are accepted up to 250 MB.</p></div></div><label class="dropzone"><input class="fileup" type="file" multiple hidden><span class="drop-icon">⇧</span><b>Drop files here or browse</b><span>Multiple files · originals stay in your configured storage · extraction runs in the background</span></label>'+(S.uploadProgress?'<div class="upload-panel"><b>'+esc(S.uploadProgress.name)+'</b><progress class="progress" max="100" value="'+S.uploadProgress.percent+'"></progress><span>'+S.uploadProgress.percent+'%</span></div>':'')+'<div class="file-grid">'+(S.files.length?S.files.map(x=>'<article class="file-card"><div class="file-type">'+esc((x.kind||'file').toUpperCase())+'</div><div class="file-copy"><b>'+esc(x.name)+'</b><span>'+formatBytes(x.size)+' · '+esc(x.extraction||'queued')+'</span><p>'+esc(x.preview||x.error||statusCopy(x))+'</p></div><div class="file-actions">'+(x.downloadable?'<button class="btn" data-download-file="'+x.id+'">Download</button>':'')+'<button class="btn danger" data-f="'+x.id+'">Delete</button></div></article>').join(''):'<div class="empty">No files uploaded yet.</div>')+'</div>');const dz=$('.dropzone'),input=$('.fileup');input.onchange=upload;for(const ev of['dragenter','dragover'])dz.addEventListener(ev,e=>{e.preventDefault();dz.classList.add('drag')});for(const ev of['dragleave','drop'])dz.addEventListener(ev,e=>{e.preventDefault();dz.classList.remove('drag')});dz.addEventListener('drop',e=>upload([...e.dataTransfer.files]));$$('[data-download-file]').forEach(b=>b.onclick=()=>window.location='/api/files/'+b.dataset.downloadFile+'/download');$$('[data-f]').forEach(b=>b.onclick=async()=>{if(await deleteStoredItem('file',b.dataset.f))files()});clearTimeout(S.filePoll);if(S.files.some(x=>x.status==='processing'))S.filePoll=setTimeout(()=>S.page==='Files'&&files(),900)}
function formatBytes(n){if(n<1024)return n+' B';if(n<1048576)return(n/1024).toFixed(1)+' KB';return(n/1048576).toFixed(1)+' MB'}function statusCopy(x){return x.status==='processing'?'Extracting searchable content…':'Stored locally and ready.'}async function plugins(){const marketplaceLabel='Plugin marketplace';const d=await api('/api/plugins');S.plugins=d.catalog||[];S.pluginConnections=d.connections||[];const q=(S.pluginSearch||'').toLowerCase(),items=S.plugins.filter(x=>!q||(x.name+' '+x.description+' '+x.category).toLowerCase().includes(q)),installed=items.filter(x=>x.connected),groups=[...new Set(items.filter(x=>!x.connected).map(x=>x.category))];content('<section class="plugins-chatgpt"><header class="plugins-top"><div><span class="eyebrow">Official app connections</span><h2>Plugins</h2><p>Authorize on the provider website, then use connected apps directly in chat.</p></div><label class="plugin-search"><span>⌕</span><input placeholder="Search plugins" value="'+esc(S.pluginSearch)+'"></label></header>'+(installed.length?'<section class="installed-strip"><div class="plugin-section-title"><b>Installed</b><span>'+installed.length+'</span></div><div class="installed-icons">'+installed.map(x=>'<button data-connect="'+x.id+'" title="'+esc(x.name)+'"><span>'+esc(x.icon)+'</span><small>'+esc(x.name)+'</small></button>').join('')+'</div></section>':'')+'<div class="plugin-categories">'+groups.map(cat=>'<section class="plugin-category"><div class="plugin-section-title"><b>'+esc(cat)+'</b><span>'+items.filter(x=>x.category===cat&&!x.connected).length+'</span></div><div class="plugin-list">'+items.filter(x=>x.category===cat&&!x.connected).map(pluginCard).join('')+'</div></section>').join('')+'</div><div class="market-note"><b>Official authorization</b><span>OAuth connections open the provider website and return to Fabric. Each deployment must register its own OAuth app and client credentials. Universal Webhook and REST API remain available for services without OAuth.</span></div></section>');$('.plugin-search input').oninput=e=>{S.pluginSearch=e.target.value;plugins()};$$('[data-connect]').forEach(b=>b.onclick=()=>connectPlugin(b.dataset.connect));$$('[data-disconnect]').forEach(b=>b.onclick=()=>disconnectPlugin(b.dataset.disconnect));$$('[data-test-plugin]').forEach(b=>b.onclick=()=>testPlugin(b.dataset.testPlugin))}
function pluginCard(x){const available=x.connected?'Connected':x.oauthProvider?(x.oauthReady?'Official':'Setup required'):'Coming soon';return '<article class="plugin-row"><div class="plugin-logo">'+esc(x.icon)+'</div><div class="plugin-copy"><b>'+esc(x.name)+'</b><small>'+esc(x.description)+'</small></div><span class="plugin-auth-type">'+available+'</span>'+(x.connected?'<button class="btn small" data-test-plugin="'+x.connectionId+'">Test</button><button class="btn small danger" data-disconnect="'+x.connectionId+'">Remove</button>':'<button class="plugin-plus" data-connect="'+x.id+'" aria-label="'+(x.oauthReady?'Connect ':'View ')+esc(x.name)+'">＋</button>')+'</article>'}
function connectorAuthorization(x){const provider=esc(x.oauthProvider||x.name),b=document.createElement('div');b.className='modalbg';b.innerHTML='<div class="modal connector-modal" role="dialog" aria-modal="true"><div class="connector-relationship"><span class="fabric-connector-mark">F</span><i></i><span class="plugin-logo large">'+esc(x.icon)+'</span></div><h2>Connect '+esc(x.name)+' to Fabric</h2><p class="connector-lead">You will continue to the official '+provider+' website to authorize this connection.</p><section class="connector-permissions"><b>Fabric will be able to</b><ul><li>Read content you explicitly select for chat</li><li>Use the permissions shown by '+provider+' before you approve</li><li>Disconnect this integration at any time</li></ul></section><p class="connector-risk">Only approve if you trust this local Fabric deployment. The provider controls its authorization screen and permission details.</p><div class="mactions"><button class="btn cancel">Cancel</button><button class="btn primary continue-provider">Continue to '+provider+'</button></div></div>';document.body.append(b);$('.cancel',b).onclick=()=>b.remove();b.onclick=e=>{if(e.target===b)b.remove()};$('.continue-provider',b).onclick=async()=>{const q=$('.continue-provider',b);q.disabled=true;q.textContent='Opening '+provider+'…';try{const r=await api('/api/plugins/oauth/'+encodeURIComponent(x.id)+'/start');location.href=r.url}catch(e){q.disabled=false;q.textContent='Continue to '+provider;toast(e.message,true)}}}
async function connectPlugin(id){const x=S.plugins.find(p=>p.id===id);if(!x)return;if(x.connected)return modal(x.name,'<div class="connect-intro"><div class="plugin-logo large">'+esc(x.icon)+'</div><p>Connected and available directly in chat.</p></div><p class="form-hint">Open Chat and choose Plugins to include this connection in a conversation.</p>',null);if(!x.oauthProvider)return modal(x.name,'<div class="connect-intro"><div class="plugin-logo large">'+esc(x.icon)+'</div><p>'+esc(x.description)+'</p></div><div class="coming-soon">Official connector coming soon</div><p class="form-hint">Fabric no longer accepts plugin API keys or arbitrary API endpoints.</p>',null);if(!x.oauthReady)return modal(x.name+' connector','<div class="connect-intro"><div class="plugin-logo large">'+esc(x.icon)+'</div><p>This official connector is not enabled in this Fabric deployment.</p></div><div class="coming-soon">Deployment setup required</div><p class="form-hint">Ask the deployment owner to enable the official '+esc(x.oauthProvider)+' OAuth connector. No API key is entered in Fabric.</p>',null);connectorAuthorization(x)}

