async function loadAgentFiles(){S.files=(await api('/api/files')).items;S.analystFiles=S.analystFiles.filter(id=>S.files.some(f=>f.id===id))}
function analystChart(c){return renderAnalystChart(c)}
async function loadAnalystProfile(){if(!S.analystFiles.length){S.analystProfile=null;return}try{S.analystProfile=await api('/api/agents/data-profile',{method:'POST',body:JSON.stringify({fileIds:S.analystFiles})})}catch(e){toast('File profile: '+e.message,true)}}
function dataTable(f){const rows=Array.isArray(f.previewRows)?f.previewRows:[],names=rows.length?[...new Set(rows.flatMap(Object.keys))].slice(0,30):(f.columns||[]).map(x=>x.name).slice(0,30);if(!rows.length)return'<div class="dataset-empty">No structured rows could be previewed for this file.</div>';return'<div class="dataset-scroll"><table class="dataset-table"><thead><tr>'+names.map(x=>'<th>'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'+rows.slice(0,100).map(row=>'<tr>'+names.map(name=>'<td>'+esc(row[name]??'')+'</td>').join('')+'</tr>').join('')+'</tbody></table></div><div class="table-foot">Showing '+Math.min(100,rows.length)+' preview rows</div>'}
function profileOutput(p){const files=p?.files||[];if(!files.length)return'<div class="analyst-empty"><span>◫</span><h3>Upload a dataset to begin</h3><p>Fabric will immediately show the uploaded rows and a complete dataset profile.</p></div>';return'<div class="dataset-workspace">'+files.map(f=>'<section class="dataset-section"><div class="dataset-heading"><div><span class="eyebrow">Table 1</span><h2>Uploaded data · '+esc(f.name)+'</h2></div><span class="dataset-badge">'+esc(f.rows??0)+' rows</span></div>'+dataTable(f)+'</section><section class="dataset-section"><div class="dataset-heading"><div><span class="eyebrow">Table 2</span><h2>Dataset information</h2><p>'+esc(f.kind)+' · '+esc((f.columns||[]).length)+' columns · '+esc(f.qualityScore??'—')+'% completeness</p></div></div>'+(f.columns?.length?'<div class="dataset-scroll"><table class="dataset-table profile-table"><thead><tr><th>Column</th><th>Data type</th><th>Missing</th><th>Unique</th><th>Range / sample</th></tr></thead><tbody>'+f.columns.slice(0,60).map(c=>'<tr><td>'+esc(c.name)+'</td><td>'+esc(c.type)+'</td><td>'+esc(c.missing)+'</td><td>'+esc(c.unique)+'</td><td>'+esc(c.range||c.sample||'—')+'</td></tr>').join('')+'</tbody></table></div>':'<div class="dataset-empty">'+esc(f.note||'No structured columns detected.')+'</div>')+'</section>').join('')+'</div>'}
function analystPipeline(){const steps=['Intent','Discovery','Profiling','Cleaning','Modeling','KPIs','Visuals','Layout','Calculations','Render','Validate','Refine'],done=new Set(S.analystStages||[]);return'<div class="analyst-pipeline" aria-label="Analysis workflow">'+steps.map((x,i)=>'<span class="'+(done.has(x)?'done':S.analystBusy&&i===0?'active':'')+'"><b>'+(done.has(x)?'✓':i+1)+'</b>'+x+'</span>').join('')+'</div>'}
function analystConversation(){return'<div class="analyst-chat-log" role="log" aria-label="Data analyst conversation">'+(S.analystMessages.length?S.analystMessages.map(m=>'<article class="analyst-message '+m.role+'"><div class="analyst-message-content"><b>'+(m.role==='assistant'?'Fabric analyst':'You')+'</b><div class="analyst-message-body">'+md(m.content)+'</div>'+(m.operation?.type?'<small>'+esc(m.operation.type.replaceAll('_',' '))+'</small>':'')+'</div></article>').join(''):'<div class="analyst-chat-empty"><b>Talk with your data analyst</b><span>Ask a question, request cleaning, define a metric, or create a dashboard.</span></div>')+'</div>'}
function dashboardFilters(d){const cols=d?.semanticModel?.columns?.filter(c=>['dimension','demographic','outcome'].includes(c.role)&&c.sampleValues?.length)||[],active=Object.fromEntries((d.filters||[]).map(f=>[f.column,f.values||[]]));return'<div class="bi-filterbar"><b>Filters</b>'+cols.slice(0,6).map(c=>'<label><span>'+esc(c.name)+'</span><select data-bi-filter="'+esc(c.name)+'"><option value="">All</option>'+c.sampleValues.map(v=>'<option value="'+esc(v)+'" '+((active[c.name]||[]).includes(String(v))?'selected':'')+'>'+esc(v)+'</option>').join('')+'</select></label>').join('')+'<button class="btn analyst-clear-filter" '+((d.filters||[]).length?'':'disabled')+'>Clear filters</button></div>'}
function dataQualityPanel(q){if(!q)return'';return'<section class="bi-section quality-section"><div class="bi-section-head"><div><span class="eyebrow">Data quality</span><h3>Trust and limitations</h3></div></div><div class="quality-grid"><article><b>'+esc(q.completeness)+'%</b><span>Completeness</span></article><article><b>'+esc(q.missingCells)+'</b><span>Missing values</span></article><article><b>'+esc(q.duplicates)+'</b><span>Duplicates</span></article><article><b>'+esc(q.invalidValues)+'</b><span>Invalid values</span></article></div></section>'}
function dashboardDetails(d){const rows=d?.details?.rows||[],names=d?.details?.columns||[];if(!rows.length)return'';return'<section class="bi-section"><div class="bi-section-head"><div><span class="eyebrow">Details</span><h3>Underlying records</h3></div></div><div class="dataset-scroll"><table class="dataset-table"><thead><tr>'+names.map(n=>'<th>'+esc(n)+'</th>').join('')+'</tr></thead><tbody>'+rows.slice(0,100).map(row=>'<tr>'+names.map(n=>'<td>'+esc(row[n]??'')+'</td>').join('')+'</tr>').join('')+'</tbody></table></div></section>'}
function visualCard(x){return'<article class="chart-card relational-chart '+esc(x.section||'main')+'" data-chart="'+esc(x.id)+'"><div class="chart-title"><div><span>'+esc((x.section||'analysis').replaceAll('_',' '))+'</span><h3>'+esc(x.purpose||x.title||'Chart')+'</h3><p>'+esc(x.analyticalQuestion||'')+'</p></div><button class="btn small analyst-explain" data-explain-visual="'+esc(x.id)+'">Explain</button></div>'+analystChart(x)+'<div class="chart-provenance">'+esc(x.aggregation||'')+(x.provenance?.rowsIncluded!=null?' · '+esc(x.provenance.rowsIncluded)+' rows':'')+'</div></article>'}
function analystDashboard(r){const d=r?.dashboard||r||{},k=Array.isArray(d.kpis)?d.kpis:[],visuals=Array.isArray(d.visuals)?d.visuals:(d.charts||[]),main=visuals.filter(v=>['main','segments'].includes(v.section)),drivers=visuals.filter(v=>v.section==='drivers'),rest=visuals.filter(v=>!['main','segments','drivers'].includes(v.section));return'<div class="power-dashboard"><header class="power-dashboard-head"><div><span class="eyebrow">Conversational BI dashboard · v'+esc(d.version||1)+'</span><h2>'+esc(d.title||'Data dashboard')+'</h2><p>'+esc(d.story?.theme||'Evidence-backed analysis')+'</p></div><div class="dashboard-actions"><button class="btn analyst-undo" '+(S.analystState?.versions?.length?'':'disabled')+'>Undo</button><button class="btn analyst-refresh">Refresh</button><button class="btn analyst-download">Export JSON</button></div></header>'+dashboardFilters(d)+(k.length?'<section class="bi-section"><div class="bi-section-head"><div><span class="eyebrow">Executive overview</span><h3>Key metrics</h3></div></div><div class="kpi-grid">'+k.map(x=>'<article class="kpi"><span>'+esc(x.name||x.label)+'</span><b>'+esc(x.value)+'</b><small>'+esc(x.semanticMeaning||x.detail||'')+'</small><button class="metric-info" title="'+esc(x.expression||'')+'">ƒx</button></article>').join('')+'</div></section>':'')+'<section class="bi-story"><span class="eyebrow">AI Data Story</span><p>'+esc(d.story?.summary||'')+'</p></section>'+(d.insights?.length?'<section class="bi-findings"><div class="bi-section-head"><div><span class="eyebrow">Key findings</span><h3>Evidence-backed signals</h3></div></div><div class="finding-grid">'+d.insights.map(x=>'<article><b>'+esc(x.finding)+'</b><small>'+esc(x.metric||'')+(x.evidence?.rows?' · '+esc(x.evidence.rows)+' rows':'')+'</small></article>').join('')+'</div></section>':'')+(main.length?'<section class="bi-section"><div class="bi-section-head"><div><span class="eyebrow">Main analysis</span><h3>What happened and where</h3></div></div><div class="chart-grid relational-grid">'+main.map(visualCard).join('')+'</div></section>':'')+(drivers.length?'<section class="bi-section"><div class="bi-section-head"><div><span class="eyebrow">Drivers & relationships</span><h3>What appears associated</h3></div></div><div class="chart-grid relational-grid">'+drivers.map(visualCard).join('')+'</div></section>':'')+(rest.length?'<section class="bi-section"><div class="bi-section-head"><div><span class="eyebrow">Supporting analysis</span><h3>Segments and details</h3></div></div><div class="chart-grid relational-grid">'+rest.map(visualCard).join('')+'</div></section>':'')+dashboardDetails(d)+dataQualityPanel(d.dataQuality)+'</div>'}
function analystOutput(r){const limitations=analystLimitations(r);if(S.analystMode==='dashboard'&&r?.dashboard)return limitations+analystDashboard(r);return limitations+profileOutput(S.analystProfile)}
async function loadAnalystState(){if(S.analystStateLoaded)return;S.analystStateLoaded=true;try{const x=await api('/api/agents/data-state');if(x.state){S.analystState=x.state;S.analystMessages=x.state.conversation||[];S.analystStages=x.state.lastExecutionStages||[];if(x.state.activeDashboard){S.analystResult={dashboard:x.state.activeDashboard};S.analystMode='dashboard'}}}catch{}}
async function agents(){if(S.agentView==='task'&&S.me.persistence==='postgres')return taskAgent();await Promise.all([loadProviders(),loadAgentFiles(),loadAnalystState()]);const picks=modelChoices();let chosen=picks.find(x=>x.providerId===S.analystProviderId&&x.modelId===S.analystModelId)||picks.find(x=>x.modelId===FABRIC_MODEL_ID)||picks[0];if(chosen){S.analystProviderId=chosen.providerId;S.analystModelId=chosen.modelId}content('<div class="analyst-shell analyst-conversation-layout"><aside class="analyst-input"><div class="analyst-title"><span class="agent-icon agent-avatar"><img src="/data-analyst-agent.webp" alt=""></span><div><span class="eyebrow">Fabric specialist</span><h2>Data Analyst Agent</h2><p>Ask questions, execute analysis, and refine a persistent dashboard.</p></div></div><label class="analyst-drop compact-drop" tabindex="0"><input class="analyst-upload" type="file" multiple hidden><span>＋</span><b>Upload data</b><small>CSV, Excel, JSON and other supported files</small></label><div class="agent-files">'+(S.files.length?S.files.map(f=>'<label class="agent-file '+(S.analystFiles.includes(f.id)?'selected':'')+'"><input type="checkbox" data-agent-file="'+f.id+'" '+(S.analystFiles.includes(f.id)?'checked':'')+'><span class="file-kind">'+esc((f.kind||'file').slice(0,3).toUpperCase())+'</span><span><b>'+esc(f.name)+'</b><small>'+esc(f.status)+'</small></span></label>').join(''):'<div class="mini-empty">No files uploaded yet.</div>')+'</div><section class="analyst-chat-panel">'+analystConversation()+'<div class="analyst-composer composerwrap"><div class="composer"><textarea class="agent-query" rows="2" placeholder="Reply to your data analyst…" aria-label="Message the data analyst">'+esc(S.analystQuery||'')+'</textarea><div class="cfoot"><label class="model-bottom analyst-model-bottom"><span class="sr-only">Data analyst reasoning model</span><select class="quick-model agent-model" aria-label="Data analyst reasoning model">'+(picks.length?picks.map(x=>'<option value="'+x.key+'" '+(chosen&&x.key===chosen.key?'selected':'')+'>'+esc(x.label)+'</option>').join(''):'<option value="">Local analytics only</option>')+'</select></label><button class="btn primary send agent-analyze" '+(S.analystBusy?'disabled':'')+'>'+(S.analystBusy?'Executing…':'Send')+'</button></div></div></div></section></aside><main class="analyst-output" aria-live="polite">'+analystPipeline()+(S.analystBusy?'<div class="analyst-empty loading"><span class="pulse-core"></span><h3>Executing deterministic analysis…</h3><p>Fabric is running only the stages required for this request.</p></div>':analystOutput(S.analystResult))+'</main></div>');$('.analyst-upload').onchange=analystUpload;const drop=$('.analyst-drop');drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag')};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');analystUpload(e.dataTransfer.files)};$$('[data-agent-file]').forEach(x=>x.onchange=async()=>{S.analystFiles=x.checked?[...new Set([...S.analystFiles,x.dataset.agentFile])]:S.analystFiles.filter(id=>id!==x.dataset.agentFile);S.analystResult=null;S.analystMode='profile';S.analystStages=[];await loadAnalystProfile();await agents()});$('.agent-model').onchange=e=>{if(!e.target.value)return;const[p,m]=e.target.value.split('|').map(decodeURIComponent);S.analystProviderId=p;S.analystModelId=m};$('.agent-analyze').onclick=analystRun;$('.agent-query').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();analystRun()}};$('.analyst-download')?.addEventListener('click',downloadAnalyst);$('.analyst-undo')?.addEventListener('click',()=>analystOperation({type:'UNDO'}));$('.analyst-refresh')?.addEventListener('click',()=>analystOperation({type:'REFRESH_DASHBOARD'}));$('.analyst-clear-filter')?.addEventListener('click',()=>analystOperation({type:'CLEAR_FILTER'}));$$('[data-bi-filter]').forEach(select=>select.onchange=()=>select.value&&analystOperation({type:'APPLY_FILTER',column:select.dataset.biFilter,value:select.value}));$$('[data-explain-visual]').forEach(b=>b.onclick=()=>analystOperation({type:'EXPLAIN',visualId:b.dataset.explainVisual}));if(S.me.persistence==='postgres'){$('.content').insertAdjacentHTML('afterbegin','<button class="btn task-agent-nav">Task Agent</button>');$('.task-agent-nav').onclick=()=>{S.agentView='task';agents()}}const analystLog=$('.analyst-chat-log');if(analystLog)analystLog.scrollTop=analystLog.scrollHeight}
async function analystUpload(value){const list=[...(value?.target?.files||value||[])];for(const file of list){try{const x=await uploadRaw(file,p=>{const d=$('.analyst-drop small');if(d)d.textContent='Uploading '+file.name+' · '+p+'%'});S.analystFiles=[...new Set([...S.analystFiles,x.id])];toast(file.name+' uploaded for analysis')}catch(e){toast(e.message,true)}}for(let i=0;i<80;i++){await loadAgentFiles();if(!S.files.some(file=>S.analystFiles.includes(file.id)&&file.status==='processing'))break;await new Promise(resolve=>setTimeout(resolve,100))}S.analystResult=null;S.analystMode='profile';S.analystStages=[];await loadAnalystProfile();await agents()}
function applyAnalystResult(result){S.analystResult=result;S.analystState=result.state||S.analystState;S.analystStages=result.executionStages||[];S.analystMode=result.mode==='dashboard'&&result.dashboard?'dashboard':S.analystMode;S.analystMessages=result.state?.conversation||S.analystMessages;if(result.answer&&!S.analystMessages.some(m=>m.role==='assistant'&&m.content===result.answer))S.analystMessages.push({role:'assistant',content:result.answer,operation:result.operation})}
async function analystOperation(operation){if(!S.analystFiles.length)return toast('Upload or select at least one file',true);S.analystBusy=true;S.analystStages=['Intent'];await agents();try{const result=await api('/api/agents/dashboard-operation',{method:'POST',body:JSON.stringify({operation,fileIds:S.analystFiles})});applyAnalystResult(result)}catch(e){toast(e.message,true)}finally{S.analystBusy=false;await agents()}}
async function analystRun(){const query=$('.agent-query').value.trim();S.analystQuery='';if(!query)return toast('Enter a message for the data analyst',true);if(!S.analystFiles.length)return toast('Upload or select at least one file',true);S.analystMessages.push({role:'user',content:query});S.analystBusy=true;S.analystStages=['Intent'];await agents();try{const result=await api('/api/agents/data-analyst',{method:'POST',body:JSON.stringify({query,fileIds:S.analystFiles,providerId:S.analystProviderId,model:S.analystModelId})});applyAnalystResult(result)}catch(e){S.analystMessages.push({role:'assistant',content:'I could not complete that request: '+e.message});toast(e.message,true)}finally{S.analystBusy=false;await agents()}}
function downloadAnalyst(){if(!S.analystResult)return;const u=URL.createObjectURL(new Blob([JSON.stringify(S.analystResult,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='fabric-data-analysis.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
boot();

async function waitForJob(id){
 const deadline=Date.now()+300000;
 while(Date.now()<deadline){const job=await api('/api/jobs/'+encodeURIComponent(id),{noWait:true});if(job.status==='completed')return job.output;if(['failed','dead_letter','cancelled'].includes(job.status))throw Error(job.error||'Background job '+job.status);await new Promise(r=>setTimeout(r,700))}
 throw Error('The job is still running. Check its status in your workspace before retrying.');
}
async function productionSettings(tab){
 if(tab==='memory'){
  const data=await api('/api/memory?limit=50&offset='+(S.memoryOffset||0)+'&includeExpired='+String(!!S.memoryIncludeExpired));content('<section class="hero"><div><span class="eyebrow">Explicit and controllable</span><h2>Memory</h2><p>Only explicitly saved facts are retained. Semantic retrieval requires an embedding provider and uses a configurable relevance cutoff.</p></div></section><div class="card"><label><input type="checkbox" id="user-memory" '+(S.me.user.memoryEnabled!==false?'checked':'')+'> Enable my memory</label><label><input type="checkbox" id="workspace-memory" '+(S.me.workspace.memoryEnabled!==false?'checked':'')+'> Enable workspace memory (administrators)</label></div><div class="card"><label for="memory-content">Save a useful fact—not a secret</label><textarea id="memory-content" maxlength="2000"></textarea><select id="memory-scope"><option value="user">Personal</option><option value="workspace">Workspace</option></select><label for="memory-expiry">Expires (optional; within one year)</label><input id="memory-expiry" type="datetime-local"><button class="btn primary" id="save-memory">Save memory</button><button class="btn" id="index-memory">Index pending memories (up to 50)</button></div>'+rows(data.items,m=>'<div><b>'+esc(m.scope)+'</b><p>'+esc(m.content)+'</p><span class="meta">Index: '+esc(m.indexingStatus||'pending')+(m.expiresAt?' · '+(m.expired?'Expired: ':'Expires: ')+esc(new Date(m.expiresAt).toLocaleString()):' · No expiry')+'</span></div><button class="btn" data-delete-memory="'+esc(m.id)+'">Delete</button>','No saved memories')+'<div class="card"><label><input id="include-expired-memories" type="checkbox" '+(S.memoryIncludeExpired?'checked':'')+'> Include expired memories for review</label><button class="btn" id="memory-previous" '+(!(S.memoryOffset>0)?'disabled':'')+'>Previous page</button><button class="btn" id="memory-next" '+(data.nextOffset==null?'disabled':'')+'>Next page</button></div>');
  $('#include-expired-memories').onchange=async e=>{S.memoryIncludeExpired=e.target.checked;S.memoryOffset=0;await settings()};$('#memory-previous').onclick=async()=>{S.memoryOffset=Math.max(0,(S.memoryOffset||0)-50);await settings()};$('#memory-next').onclick=async()=>{if(data.nextOffset!=null){S.memoryOffset=data.nextOffset;await settings()}};
  $('#index-memory').onclick=async e=>{e.target.disabled=true;try{const result=await api('/api/memory/reindex',{method:'POST',body:JSON.stringify({limit:50})});toast('Indexed '+result.indexed+' memories'+(result.skippedSensitive?'; '+result.skippedSensitive+' sensitive memories skipped—review and remove them.':'')+(result.nextCursor?'; more pending memories remain.':''));await settings()}catch(x){toast(x.message,true);e.target.disabled=false}};
  $('#save-memory').onclick=async()=>{try{await api('/api/memory',{method:'POST',body:JSON.stringify({content:$('#memory-content').value,scope:$('#memory-scope').value,expiresAt:$('#memory-expiry').value?new Date($('#memory-expiry').value).toISOString():null})});S.memoryOffset=0;settings()}catch(e){toast(e.message,true)}};
  for(const [id,workspace] of [['user-memory',false],['workspace-memory',true]])$('#'+id).onchange=async e=>{try{await api('/api/memory',{method:'PATCH',body:JSON.stringify({enabled:e.target.checked,workspace})});if(workspace)S.me.workspace.memoryEnabled=e.target.checked;else S.me.user.memoryEnabled=e.target.checked}catch(x){e.target.checked=!e.target.checked;toast(x.message,true)}};
  $$('[data-delete-memory]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this memory?'))return;try{await api('/api/memory/'+encodeURIComponent(b.dataset.deleteMemory),{method:'DELETE'});settings()}catch(e){toast(e.message,true)}});
 }else if(tab==='usage'){
  const [data,limits]=await Promise.all([api('/api/usage'),api('/api/usage/limits')]);content('<section class="hero"><div><h2>Usage and cost</h2><p>Daily model usage for the past 31 days. Missing price configuration is not a free request.</p></div></section>'+aiLimitsCard(limits)+'<div class="tablewrap"><table class="table"><thead><tr><th>Day</th><th>Model</th><th>Requests</th><th>Input tokens</th><th>Output tokens</th><th>Known estimated cost (USD)</th></tr></thead><tbody>'+(data.items||[]).map(x=>'<tr><td>'+esc(new Date(x.day).toLocaleDateString())+'</td><td>'+esc(x.model)+'</td><td>'+esc(x.requests)+'</td><td>'+esc(x.inputTokens)+'</td><td>'+esc(x.outputTokens)+'</td><td>'+esc(x.hasUnpricedRequests?'Price unavailable for some requests':Number(x.estimatedCost).toFixed(6))+'</td></tr>').join('')+'</tbody></table></div>');
 }else if(tab==='sessions'){
  const data=await api('/api/auth/sessions');content('<section class="hero"><div><h2>Active sessions</h2><p>Revoke a device’s session without changing your password.</p></div></section><div class="card"><h3>Email verification</h3><p>'+esc(S.me.user.emailVerified?'Verified':'Not yet verified')+'</p>'+(!S.me.user.emailVerified?'<button class="btn" id="request-email-verification">Queue verification email</button>':'')+'</div>'+rows(data.items,x=>'<div><b>'+esc(x.device||'Unknown device')+'</b><p>'+esc(new Date(x.createdAt).toLocaleString())+'</p></div><button class="btn" data-revoke-session="'+esc(x.id)+'">Revoke</button>','No active sessions'));
  $('#request-email-verification')?.addEventListener('click',async e=>{e.target.disabled=true;try{await api('/api/auth/verify-email',{method:'POST',body:'{}'});toast('Verification email queued. Check your inbox; delivery depends on the configured mail service.')}catch(error){toast(error.message,true)}finally{e.target.disabled=false}});
  $$('[data-revoke-session]').forEach(b=>b.onclick=async()=>{if(!confirm('Revoke this session?'))return;await api('/api/auth/sessions/'+encodeURIComponent(b.dataset.revokeSession),{method:'DELETE'});boot()});
 }else{
  const data=await api('/api/approvals');content('<section class="hero"><div><h2>Action approvals</h2><p>Review the exact operation and arguments before approving. Approvals expire and can be used only once.</p></div></section>'+rows(data.items,x=>'<div><b>'+esc(x.tool)+'</b><pre>'+esc(JSON.stringify(x.input,null,2))+'</pre><p class="meta">Expires '+esc(new Date(x.expiresAt).toLocaleString())+'</p></div><div><button class="btn primary" data-approve="'+esc(x.id)+'">Approve</button><button class="btn" data-reject="'+esc(x.id)+'">Reject</button></div>','No actions waiting for approval'));
  for(const [attr,approved] of [['approve',true],['reject',false]])$$('[data-'+attr+']').forEach(b=>b.onclick=async()=>{try{const record=data.items.find(x=>x.id===b.dataset[attr]);await api('/api/approvals/'+encodeURIComponent(record.id),{method:'POST',body:JSON.stringify({approved})});if(approved&&!record.runId)await api('/api/tools/execute',{method:'POST',body:JSON.stringify({toolId:record.tool,input:record.input,approvalId:record.id})});toast(approved?'Action approved':'Action rejected');settings()}catch(e){toast(e.message,true)}});
 }
}
async function taskAgent(){
 content('<button class="btn" id="analyst-nav">Data Analyst</button><section class="hero"><div><h2>Task Agent</h2><p>Plan, use authorized tools, observe results, and verify. Dangerous actions require explicit approval.</p></div></section><div class="card"><label for="task-objective">Objective</label><textarea id="task-objective" maxlength="20000"></textarea><button class="btn primary" id="run-task">Run task</button><button class="btn" id="stop-task" disabled>Cancel</button></div><div class="card" id="task-progress" aria-live="polite">Ready</div>');
 $('#analyst-nav').onclick=()=>{S.agentView='analyst';agents()};
 $('#run-task').onclick=async()=>{const button=$('#run-task');button.disabled=true;try{const run=await api('/api/agents/run',{method:'POST',body:JSON.stringify({task:$('#task-objective').value}),noWait:true});S.taskRunId=run.id;$('#stop-task').disabled=false;for(let i=0;i<600&&S.page==='Agents'&&S.agentView==='task';i++){const latest=await api('/api/agents/runs/'+encodeURIComponent(run.id));$('#task-progress').innerHTML='<b>'+esc(latest.status.replaceAll('_',' '))+'</b>'+(latest.plan?.steps?'<ol>'+latest.plan.steps.map(x=>'<li>'+esc(x.title)+'</li>').join('')+'</ol>':'')+(latest.output?'<p>'+esc(latest.output)+'</p>':'')+(latest.error?'<p>'+esc(latest.error)+'</p>':'')+(latest.status==='waiting_approval'?'<p>Review this action in Settings → Approvals.</p>':'');if(['completed','failed','cancelled','waiting_approval'].includes(latest.status))break;await new Promise(r=>setTimeout(r,700))}}catch(e){toast(e.message,true)}finally{button.disabled=false;if($('#stop-task'))$('#stop-task').disabled=true}};
 $('#stop-task').onclick=()=>api('/api/agents/runs/'+encodeURIComponent(S.taskRunId)+'/cancel',{method:'POST',body:'{}'});
}

function accountConfirmation(){const purpose=location.pathname.split('/').at(-1),token=new URLSearchParams(location.hash.slice(1)).get('token');history.replaceState({},'',location.pathname);$('#app').innerHTML='<main class="auth"><section class="formwrap"><form class="authform"><h2>'+esc(purpose==='reset_password'?'Reset password':'Verify email')+'</h2>'+(purpose==='reset_password'?'<label for="new-password">New password</label><input id="new-password" type="password" minlength="10" maxlength="256" required>':'<p>Confirm your email address.</p>')+'<button class="btn primary" type="submit">Confirm</button><p class="meta" id="confirmation-status"></p></form></section></main>';$('.authform').onsubmit=async e=>{e.preventDefault();try{await api('/api/auth/confirm',{method:'POST',body:JSON.stringify({purpose,token,password:$('#new-password')?.value})});$('#confirmation-status').textContent='Complete. You can now sign in.';$('.authform button').disabled=true;setTimeout(()=>location.assign('/'),1500)}catch(x){$('#confirmation-status').textContent=x.message}};}

async function deleteStoredItem(kind,id){
  if(!confirm('Delete this '+kind+'? This cannot be undone.'))return false;
  try{
    const result=await api('/api/'+(kind==='file'?'files':'artifacts')+'/'+encodeURIComponent(id),{method:'DELETE',body:'{}'});
    toast(result.storageStatus==='queued'?'Removed from workspace; storage cleanup is queued.':result.storageStatus==='failed'?'Removed from workspace; storage cleanup needs administrator review.':'Deleted',result.storageStatus==='failed');
    return true;
  }catch(error){toast(error.message,true);return false}
}

function aiLimitsCard(limits){return '<div class="card"><h3>AI admission limits</h3><p>Cloud generation/embeddings: '+(limits.cloudEnabled?'enabled by operator':'disabled by operator')+'</p><p>Your provider attempts today: '+esc(limits.userUsed)+' / '+esc(limits.userDailyLimit)+' · Workspace: '+esc(limits.workspaceUsed)+' / '+esc(limits.workspaceDailyLimit)+'</p><p>Maximum output tokens per request: '+esc(limits.maxOutputTokens)+'</p><p class="meta">Each provider attempt and embedding batch counts, including retries and failed admitted requests. Resets at midnight UTC. These are request limits—not a currency budget or a guarantee that hosting is free.</p></div>'}
